<content>import { randomUUID } from "crypto";
import type { GameVariation, GameVariationInput, VariationResponse, VariationsListResponse } from "@snake/contracts";
import type { VariationService } from "../variationService";

const STORAGE_KEY = "game-variations";

const getVariationsFromStorage = (): GameVariation[] => {
  const stored = localStorage.getItem(STORAGE_KEY);
  return stored ? JSON.parse(stored) : [];
};

const saveVariationsToStorage = (variations: GameVariation[]): void => {
  localStorage.setItem(STORAGE_KEY, JSON.stringify(variations));
};

const getCurrentProfileId = (): string | null => {
  return localStorage.getItem("activeProfileId");
};

export const localVariationService: VariationService = {
  async getVariations(): Promise<VariationsListResponse> {
    const profileId = getCurrentProfileId();
    if (!profileId) {
      throw new Error("No active profile");
    }

    const allVariations = getVariationsFromStorage();
    const variations = allVariations.filter((v) => v.profileId === profileId);
    return { variations };
  },

  async getVariation(id: string): Promise<VariationResponse> {
    const variations = getVariationsFromStorage();
    const variation = variations.find((v) => v.id === id);
    if (!variation) {
      throw new Error("Variation not found");
    }
    return { variation };
  },

  async createVariation(input: GameVariationInput): Promise<VariationResponse> {
    const profileId = getCurrentProfileId();
    if (!profileId) {
      throw new Error("No active profile");
    }

    const now = new Date().toISOString();
    const variation: GameVariation = {
      id: randomUUID(),
      profileId,
      ...input,
      usageCount: 0,
      createdAt: now,
      updatedAt: now
    };

    const variations = getVariationsFromStorage();
    variations.push(variation);
    saveVariationsToStorage(variations);

    return { variation };
  },

  async updateVariation(id: string, input: GameVariationInput): Promise<VariationResponse> {
    const profileId = getCurrentProfileId();
    if (!profileId) {
      throw new Error("No active profile");
    }

    const variations = getVariationsFromStorage();
    const index = variations.findIndex((v) => v.id === id && v.profileId === profileId);

    if (index === -1) {
      throw new Error("Variation not found or unauthorized");
    }

    const now = new Date().toISOString();
    variations[index] = {
      ...variations[index],
      ...input,
      updatedAt: now
    };

    saveVariationsToStorage(variations);
    return { variation: variations[index] };
  },

  async deleteVariation(id: string): Promise<void> {
    const profileId = getCurrentProfileId();
    if (!profileId) {
      throw new Error("No active profile");
    }

    const variations = getVariationsFromStorage();
    const filtered = variations.filter((v) => !(v.id === id && v.profileId === profileId));

    if (filtered.length === variations.length) {
      throw new Error("Variation not found or unauthorized");
    }

    saveVariationsToStorage(filtered);
  },

  async incrementUsageCount(id: string): Promise<void> {
    const variations = getVariationsFromStorage();
    const variation = variations.find((v) => v.id === id);

    if (variation) {
      variation.usageCount += 1;
      saveVariationsToStorage(variations);
    }
  }
};
</content>
</write_to_file>

Now let's create a hook for managing variations:

<write_to_file>
<path>apps/web/src/hooks/useVariation.ts</path>
<content>import { useState, useEffect, useCallback } from "react";
import type { GameVariation, GameVariationInput } from "@snake/contracts";
import { useVariationService } from "../services/variationService";

export const useVariation = () => {
  const [variations, setVariations] = useState<GameVariation[]>([]);
  const [activeVariation, setActiveVariation] = useState<GameVariation | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const service = useVariationService();

  const loadVariations = useCallback(async () => {
    try {
      setLoading(true);
      setError(null);
      const resolvedService = await service;
      const response = await resolvedService.getVariations();
      setVariations(response.variations);

      // Load active variation from localStorage
      const activeId = localStorage.getItem("activeVariationId");
      if (activeId) {
        const active = response.variations.find((v) => v.id === activeId);
        setActiveVariation(active || null);
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : "Failed to load variations");
    } finally {
      setLoading(false);
    }
  }, [service]);

  useEffect(() => {
    loadVariations();
  }, [loadVariations]);

  const createVariation = useCallback(
    async (input: GameVariationInput) => {
      try {
        setError(null);
        const resolvedService = await service;
        const response = await resolvedService.createVariation(input);
        await loadVariations();
        return response.variation;
      } catch (err) {
        const message = err instanceof Error ? err.message : "Failed to create variation";
        setError(message);
        throw new Error(message);
      }
    },
    [service, loadVariations]
  );

  const updateVariation = useCallback(
    async (id: string, input: GameVariationInput) => {
      try {
        setError(null);
        const resolvedService = await service;
        const response = await resolvedService.updateVariation(id, input);
        await loadVariations();
        return response.variation;
      } catch (err) {
        const message = err instanceof Error ? err.message : "Failed to update variation";
        setError(message);
        throw new Error(message);
      }
    },
    [service, loadVariations]
  );

  const deleteVariation = useCallback(
    async (id: string) => {
      try {
        setError(null);
        const resolvedService = await service;
        await resolvedService.deleteVariation(id);

        // Clear active variation if it was deleted
        if (activeVariation?.id === id) {
          setActiveVariation(null);
          localStorage.removeItem("activeVariationId");
        }

        await loadVariations();
      } catch (err) {
        const message = err instanceof Error ? err.message : "Failed to delete variation";
        setError(message);
        throw new Error(message);
      }
    },
    [service, loadVariations, activeVariation]
  );

  const activateVariation = useCallback(
    async (id: string) => {
      const variation = variations.find((v) => v.id === id);
      if (!variation) {
        throw new Error("Variation not found");
      }

      setActiveVariation(variation);
      localStorage.setItem("activeVariationId", id);

      // Increment usage count
      const resolvedService = await service;
      await resolvedService.incrementUsageCount(id);
    },
    [variations, service]
  );

  const clearActiveVariation = useCallback(() => {
    setActiveVariation(null);
    localStorage.removeItem("activeVariationId");
  }, []);

  return {
    variations,
    activeVariation,
    loading,
    error,
    createVariation,
    updateVariation,
    deleteVariation,
    activateVariation,
    clearActiveVariation,
    refreshVariations: loadVariations
  };
};
</content>
</write_to_file>

