              color: "white",
              fontWeight: 600,
              textTransform: "capitalize"
            }}
          />
        </Box>

        <Typography
          variant="body2"
          sx={{ color: theme.ui.leaderboard.mutedText, mb: 2, minHeight: 40 }}
        >
          {variation.description}
