          <IconActionButton
            tone="danger"
            variant="outlined"
            icon={<approvedIcons.delete />}
            iconColor={theme.icons.delete || theme.icons.default}
            label="Delete"
            onClick={() => onDelete(variation.id)}
          />
        </Box>

        {variation.usageCount > 0 && (
